import os
import json
import uuid
import sys
from alchemyst_ai import AlchemystAI

def main():
    api_key = os.environ.get("ALCHEMYST_AI_API_KEY")
    run_id = os.environ.get("ZEALT_RUN_ID", "local_run")

    if not api_key:
        print("Error: ALCHEMYST_AI_API_KEY not set")
        sys.exit(1)

    client = AlchemystAI(api_key=api_key)

    # Prepare documents
    docs_to_add = [
        {
            "content": f"The v1 engineering service is responsible for core infrastructure. MARKER_ENG_V1_{run_id}",
            "group_name": ["eng", "v1"],
            "source": "engineering_manual_v1"
        },
        {
            "content": f"The v2 engineering service handles next-gen scaling. MARKER_ENG_V2_{run_id}",
            "group_name": ["eng", "v2"],
            "source": "engineering_manual_v2"
        },
        {
            "content": f"The v1 documentation service manages public API docs. MARKER_DOCS_V1_{run_id}",
            "group_name": ["docs", "v1"],
            "source": "docs_manual_v1"
        }
    ]

    print(f"Ingesting documents for run_id: {run_id}")
    for doc in docs_to_add:
        file_name = f"doc_{uuid.uuid4().hex}_{run_id}.txt"
        try:
            client.v1.context.add(
                content=doc["content"],
                context_type="resource",
                scope="internal",
                source=doc["source"],
                metadata={
                    "file_name": file_name,
                    "group_name": doc["group_name"]
                }
            )
            print(f"Added document: {file_name} with groups {doc['group_name']}")
        except Exception as e:
            print(f"Failed to add document: {e}")
            sys.exit(1)

    # Perform search
    query = "What does the v1 engineering service do?"
    intersection_filter = ["eng", "v1"]

    print(f"Searching for: '{query}' with filter: {intersection_filter}")
    try:
        search_response = client.v1.context.search(
            query=query,
            scope="internal",
            metadata={"group_name": intersection_filter},
            similarity_threshold=0.5
        )
    except Exception as e:
        print(f"Search failed: {e}")
        sys.exit(1)

    results = []
    # search_response is a pydantic model, contexts is the list of matches
    for ctx in search_response.contexts:
        results.append({
            "id": ctx.id,
            "content": ctx.content
        })

    output = {
        "query": query,
        "intersection_filter": intersection_filter,
        "run_id": run_id,
        "results": results
    }

    output_path = "/workspace/result.json"
    with open(output_path, "w") as f:
        json.dump(output, f, indent=2)

    print(f"Results written to {output_path}")

    # Verification (optional but good for debugging in logs)
    if not results:
        print("Warning: No results found!")
    else:
        for res in results:
            print(f"Found context ID: {res['id']}")

if __name__ == "__main__":
    main()

